#pragma once

#include "pfecBaseReader.h"

namespace PFECNativeInterface {

    /// A class that provides easy access to the data inside a mesh file generated by the MeshWriter.
    /// Most of the time, the mesh should be accessed by partition
    /// instead of by inidvidual a node/element or by a global collection of nodes/elements.  This will provide
    /// the fastest access while keeping the memory requried to a managable level, since a partition is intended
    /// to be analyzed on a single computation node.  The class was written with the intention to allow
    /// the mesh to be broken up across multiple mesh files in the case of file system optimization or a non-unified
    /// file system, but the meta file format and meta reader/writer would need to be modified to allow this flexibility.
    /// Example:
    /// <code>
    /// PFECNativeInterface::MeshReader meshReader;
    /// meshReader.open("C:/mesh.bfm");
    /// for each (auto partNum in meshReader.get_parts_in_file()) {
    ///     std::vector<BF_IND> nodeIndices;
    ///     std::vector< std::vector<double> > coords;
    ///     meshReader.read_part_nodal(partNum, nodeIndices, coords);
    ///     // Do something with the nodal information for that partition, such as plotting.
    ///     // Similarily for elemental information
    /// }
    /// // When you are done reading, call close
    /// meshReader.close() // But make sure not to try to use it again.
    /// </code>
    class MeshReader : public BaseReader
    {
    public:

        /// Default constructor just sets the some variables to initial values
        MeshReader();
		/// Get the number of nodes in the global mesh
		PFEC_IND get_num_global_nodes() const { return num_global_nodes_; }
		/// Get the number of elements in the global mesh
		PFEC_IND get_num_global_elems() const { return num_global_elems_; }
		/// Get the dimension of the mesh (1D, 2D, 3D)
		PFEC_INT get_num_dims() const { return num_dims_; }
		/// Returns a vector of the domain IDs that is contained within this file.
		std::vector<PFEC_INT> get_domain_ids() { return domains_; };
        /// Get the number of nodes, elements, and dimension size for a partition
        /// of the mesh
        void get_part_sizes(const PFEC_INT partID, PFEC_INT &numNodes, PFEC_INT &numElements, PFEC_INT &numDims);
        /// Get the nodal indicies and coordinates for a partition of the mesh
        /// Parameters:
        ///   partID - the partition number to access
        /// Output Arguments:
        ///   nodeIndices - a vector of nodal indices to fill
        ///   coords - a vector of nodal coordinates (which is a vector of doubles) to fill
        void read_part_nodal(PFEC_INT partID, std::vector<PFEC_IND> &nodeIndices, std::vector<PFEC_INT> &partitions, std::vector< std::vector<double> > &coords);
		/// A shorter version of read_part_nodal above
		NodeInfo read_part_nodal(PFEC_INT partID);
        // TODO read_part_element via iterators
        /// Get the element information for a partition of the mesh
        /// Parameters:
        ///   partID - the partition number to access
        /// Output Arguments:
        ///   globalIndices - a vector of element indices to fill
		///   partitions - a vector of partition numbers to fill that indicates the partition that owns the element
		///   domains - a vector of domain numbers to fill
        ///   elemGeomTypes - a vector of element geometry types to fill
        ///   localConnectivity - a vector of element connectivities (which is a vector of PFEC_INT> to fill, note that
        ///                       the connectivity is based on the local numbering, which is implied.
		void read_part_element(PFEC_INT partID, std::vector<PFEC_IND> &globalIndices, std::vector<PFEC_INT> &partitions, std::vector<PFEC_INT> &domains,
                               std::vector<ElemGeomType> &elemGeomTypes, std::vector< std::vector<PFEC_INT>> &localConnectivity);
		/// A shorter version of read_part_element above
		ElementInfo read_part_element(PFEC_INT partID);
		// TODO read_part_element via iterators

        /// Will clean up all the memory allocated and close the mesh file.
        virtual void close();

    protected:
        //////////////////////////////////
        // Protected properties/methods //
        //////////////////////////////////

        // Important mesh information to store
        PFEC_IND num_global_nodes_;
        PFEC_IND num_global_elems_;
        PFEC_INT num_dims_;
		std::vector<PFEC_INT> domains_;
        PFEC_INT num_global_parts_;
        /// Positions of the beginning of node data by local partition index (0-P)
        std::vector<std::streamoff> node_lookup_table_;
        /// Positions of the beginning of element data by local partition index (0-P)
        std::vector<std::streamoff> elem_lookup_table_;

        /// Checks some common things for the methods in the class
        void common_error_checks(PFEC_INT partID);

        /// Reads the header information (called by open)
        virtual void read_header_info();
    };

};